public final class CompanionDeployRequestService {
    private CompanionDeployRequestService() {
    }

    public static Result request(ServerPlayer player, PlayerCompanionData data, CompanionKind kind, UUID uuid, Mode mode, String source) {
        return CompanionDeployRequestService.request(player, data, kind, uuid, mode, source, (CompanionDeploymentPlan)null);
    }

    public static Result request(ServerPlayer player, PlayerCompanionData data, CompanionKind kind, UUID uuid, Mode mode, String source, BlockPos plannedSpawn) {
        CompanionDeploymentPlan plan = plannedSpawn == null ? null : CompanionDeploymentPlan.tactical(CompanionDeploymentPlan.Intent.ORDINARY, null, plannedSpawn, null);
        return CompanionDeployRequestService.request(player, data, kind, uuid, mode, source, plan);
    }

    public static Result request(ServerPlayer player, PlayerCompanionData data, CompanionKind kind, UUID uuid, Mode mode, String source, CompanionDeploymentPlan plan) {
        return CompanionDeployRequestService.request(player, data, kind, uuid, mode, source, plan, true);
    }

    public static Result requestExternalTask(ServerPlayer player, PlayerCompanionData data, CompanionKind kind, UUID uuid, String source) {
        return CompanionDeployRequestService.request(player, data, kind, uuid, Mode.AUTONOMOUS, source, null, false);
    }

    public static Result requestExternalTask(ServerPlayer player, PlayerCompanionData data, CompanionKind kind, UUID uuid, String source, CompanionDeploymentPlan plan) {
        return CompanionDeployRequestService.request(player, data, kind, uuid, Mode.AUTONOMOUS, source, plan, false, true);
    }

    public static Result requestExternalTaskSilent(ServerPlayer player, PlayerCompanionData data, CompanionKind kind, UUID uuid, String source, CompanionDeploymentPlan plan) {
        return CompanionDeployRequestService.request(player, data, kind, uuid, Mode.AUTONOMOUS, source, plan, false, false);
    }

    public static Result requestExternalDeploySilent(ServerPlayer player, PlayerCompanionData data, CompanionKind kind, UUID uuid, String source) {
        return CompanionDeployRequestService.request(player, data, kind, uuid, Mode.AUTONOMOUS, source, null, true, false);
    }

    private static Result request(ServerPlayer player, PlayerCompanionData data, CompanionKind kind, UUID uuid, Mode mode, String source, CompanionDeploymentPlan plan, boolean countTowardDeploymentLimit) {
        return CompanionDeployRequestService.request(player, data, kind, uuid, mode, source, plan, countTowardDeploymentLimit, true);
    }

    private static Result request(ServerPlayer player, PlayerCompanionData data, CompanionKind kind, UUID uuid, Mode mode, String source, CompanionDeploymentPlan plan, boolean countTowardDeploymentLimit, boolean presentationEnabled) {
        if (data.isRecovery(uuid)) {
            return new Result(State.REJECTED, null);
        }
        LivingEntity ready = CompanionDeployRequestService.readyEntity(player, data, uuid, mode);
        if (ready != null && !CompanionLifecycleFacade.isBusy(player, data, uuid)) {
            return new Result(State.READY, ready);
        }
        if (CompanionSummonApproachService.isActive(uuid)) {
            return new Result(State.WAITING, null);
        }
        if (CompanionLifecycleFacade.isBusy(player, data, uuid)) {
            return new Result(State.WAITING, null);
        }
        if (mode != Mode.AUTONOMOUS && !uuid.equals(data.active(kind).orElse(null))) {
            data.setActiveUuid(kind, uuid);
            CompanionDataService.save(player, data);
            CompanionSyncService.syncToClient(player, kind);
        }
        if (mode == Mode.AUTONOMOUS) {
            return CompanionDeployRequestService.deployDirect(player, data, kind, uuid, source, plan, countTowardDeploymentLimit, presentationEnabled);
        }
        boolean accepted = mode == Mode.AUTONOMOUS ? CompanionLifecycleFacade.summonActiveForTacticalOrder(player, data, kind, source) : CompanionLifecycleFacade.summonActive(player, data, kind, source);

